1	// In-memory live-editing state layered on top of a loaded LandscapeSnapshot,
2	// plus validation and residual-CLI command-line generation.
3	//
4	// Pure, DOM-free, framework-free — see web/src/model.test.ts and the
5	// governing plan at residual/iterations/view-live-editing-plan.md (Phase 4).
6	// Sits between the embedded snapshot JSON (src/view/snapshot.rs's
7	// `LandscapeSnapshot`) and import-parser.ts's CLI-text parsing: this module
8	// owns "what has the user added/changed/toggled this session" plus
9	// validation, and turns that state back into `residual add`/`residual
10	// update` command-line text.
11	//
12	// Design notes (decisions made beyond the task sketch, documented per
13	// instructions):
14	//
15	// - `SnapshotAttractor` includes `description` even though the sketch in the
16	//   task omitted it: `residual add attractor --description` is a *required*
17	//   flag per web/generated/cli-schema.json ("add attractor" ->
18	//   description: required=true), and src/view/snapshot.rs's
19	//   `SnapshotAttractor` carries it too. Dropping it would make
20	//   `toCommandLines` unable to ever emit a valid `add attractor` line.
21	// - Required-fields ground truth for validation comes from
22	//   web/generated/cli-schema.json, NOT the plan prose. Per that schema,
23	//   `add stressor`/`add purpose` require description, attractor-id and
24	//   naive-change/feature — but NOT outcomes (outcomes: required=false in the
25	//   schema for both). `isForceValid` therefore does not check outcomes.
26	// - `add stressor`/`add purpose` have no `--add-component` flag in the
27	//   schema (only `update stressor`/`update purpose` do). So a freshly
28	//   *added* force's toggled components can never ride on its own `add`
29	//   line — they always surface as a follow-up
30	//   `update <type> --force-id <tempId> --add-component ...` entry, addressed
31	//   by the force's `tempId` as a placeholder for the real id the CLI will
32	//   assign at add-time (resolving that placeholder to a real id is a
33	//   runtime/Phase-7 bash-script concern, out of scope for this pure-model
34	//   layer). This is why such synthetic entries land in the *update*
35	//   ordering phase even though the force itself is brand new this session.
36	// - Personas and terms are tracked as their own add/update buckets even
37	//   though the plan's explicit ordering list only names "components,
38	//   attractors, personas, forces" (terms are not mentioned). Since terms
39	//   don't participate in the NKP matrix and aren't named in the ordering
40	//   rule, this module places them last, after forces, in both the add and
41	//   update phases — a conservative extension of the rule, not a
42	//   contradiction of it.
43	
44	/** A landscape attractor, as it appears in the embedded snapshot or is added this session. */
45	export interface SnapshotAttractor {
46	  id: string;
47	  name: string;
48	  /** Required by `residual add attractor --description`; see module notes. */
49	  description: string;
50	  positiveState: string;
51	  negativeState: string;
52	}
53	
54	/** A landscape component (NKP matrix column). */
55	export interface SnapshotComponent {
56	  name: string;
57	  description: string;
58	  status: "proposed" | "actual";
59	  architectureSet: string;
60	}
61	
62	/** A stressor or purpose force (NKP matrix row), with its coupled components. */
63	export interface SnapshotForce {
64	  id: string;
65	  kind: "stressor" | "purpose";
66	  description: string;
67	  attractorId: string;
68	  /** `naive_change` for stressors, `feature` for purposes. */
69	  naiveChangeOrFeature: string;
70	  outcomes: string;
71	  shortname: string;
72	  /** Component names currently coupled to this force via residues.csv. */
73	  components: string[];
74	}
75	
76	/** A defense/below-table persona (name + role), not part of the NKP matrix. */
77	export interface SnapshotPersona {
78	  name: string;
79	  role: string;
80	  concerns?: string;
81	  desires?: string;
82	}
83	
84	/** A lexicon term, not part of the NKP matrix. */
85	export interface SnapshotTerm {
86	  term: string;
87	  definition: string;
88	  domain?: string;
89	  related?: string;
90	}
91	
92	/** A newly-added force this session, not yet assigned a real force id by the CLI. */
93	export type AddedForce = SnapshotForce & { tempId: string };
94	
95	/** Partial update to an existing (or newly-added) force, keyed by real id or tempId. */
96	export type ForceUpdate = Partial<Omit<SnapshotForce, "id" | "kind">>;
97	
98	/** Partial update to an existing attractor, keyed by real id. */
99	export type AttractorUpdate = Partial<Omit<SnapshotAttractor, "id">>;
100	
101	/** Partial update to an existing component, keyed by name (components have no separate id). */
102	export type ComponentUpdate = Partial<Omit<SnapshotComponent, "name">>;
103	
104	/** Partial update to an existing persona, keyed by name. */
105	export type PersonaUpdate = Partial<Omit<SnapshotPersona, "name">>;
106	
107	/** Partial update to an existing term, keyed by term text. */
108	export type TermUpdate = Partial<Omit<SnapshotTerm, "term">>;
109	
110	/**
111	 * Everything the user has added or changed this editing session, layered on
112	 * top of a base snapshot loaded from the embedded `residual-snapshot` JSON.
113	 */
114	export interface PendingState {
115	  baseAttractors: SnapshotAttractor[];
116	  baseComponents: SnapshotComponent[];
117	  baseForces: SnapshotForce[];
118	  basePersonas: SnapshotPersona[];
119	  baseTerms: SnapshotTerm[];
120	
121	  addedAttractors: SnapshotAttractor[];
122	  addedComponents: SnapshotComponent[];
123	  addedForces: AddedForce[];
124	  addedPersonas: SnapshotPersona[];
125	  addedTerms: SnapshotTerm[];
126	
127	  /** Keyed by real attractor id. */
128	  updatedAttractors: Record<string, AttractorUpdate>;
129	  /** Keyed by component name. */
130	  updatedComponents: Record<string, ComponentUpdate>;
131	  /** Keyed by real force id OR an added force's tempId. */
132	  updatedForces: Record<string, ForceUpdate>;
133	  /** Keyed by persona name. */
134	  updatedPersonas: Record<string, PersonaUpdate>;
135	  /** Keyed by term text. */
136	  updatedTerms: Record<string, TermUpdate>;
137	}
138	
139	/** Required (non-outcomes) field names for a stressor/purpose, per cli-schema.json. */
140	export type RequiredForceField = "description" | "attractorId" | "naiveChangeOrFeature";
141	
142	export const REQUIRED_FORCE_FIELDS: readonly RequiredForceField[] = [
143	  "description",
144	  "attractorId",
145	  "naiveChangeOrFeature",
146	];
147	
148	/** One resolved item in the fixed add/update, component/attractor/persona/term/force emission order. */
149	export interface OrderedEntry {
150	  bucket: "component" | "attractor" | "persona" | "term" | "force";
151	  action: "add" | "update";
152	  /** Real id/name/term/tempId identifying the entry within its bucket. */
153	  key: string;
154	}
155	
156	/**
157	 * Returns whether a force (added, or the effective merge of a base force
158	 * with its pending update) is valid: every field in REQUIRED_FORCE_FIELDS is
159	 * non-empty, AND at least one component is toggled on (per the plan: "no
160	 * components selected is invalid"). Outcomes is intentionally not checked —
161	 * it is not required by `add stressor`/`add purpose` in cli-schema.json.
162	 */
163	export function isForceValid(force: {
164	  description: string;
165	  attractorId: string;
166	  naiveChangeOrFeature: string;
167	  components: string[];
168	}): boolean {
169	  throw new Error("not yet implemented — green phase");
170	}
171	
172	/** Per-state validity: which forces (by id/tempId) are invalid, and why. */
173	export interface StateValidity {
174	  invalidForceIds: Set<string>;
175	  /** Reasons per invalid force id/tempId, e.g. ["description", "components"]. */
176	  invalidReasonsByForce: Record<string, string[]>;
177	}
178	
179	/**
180	 * Computes validity across the whole current state: every base force merged
181	 * with its pending update (if any), plus every added force. Used later to
182	 * drive red-highlighting of invalid cells/rows/sticky headers (Phase 5).
183	 */
184	export function computeStateValidity(state: PendingState): StateValidity {
185	  throw new Error("not yet implemented — green phase");
186	}
187	
188	/**
189	 * Flattens a PendingState into the fixed emission order: components,
190	 * attractors, personas, terms, forces — with every addition across every
191	 * bucket ordered before every update across every bucket (see module notes
192	 * re: terms, and re: added forces with toggled components synthesizing a
193	 * follow-up "update" entry keyed by their tempId).
194	 */
195	export function orderedEntries(state: PendingState): OrderedEntry[] {
196	  throw new Error("not yet implemented — green phase");
197	}
198	
199	/** One rendered `residual add`/`residual update` command line, with its validity. */
200	export interface CommandLine {
201	  line: string;
202	  valid: boolean;
203	}
204	
205	/**
206	 * Renders a PendingState into ordered `residual add`/`residual update`
207	 * command-line text (see orderedEntries for ordering), quoting every flag
208	 * value in double quotes and escaping embedded `"` as `\"`, mirroring
209	 * import-parser.ts's `tokenizeCommandLine` so lines round-trip through its
210	 * `parseImportText`. Lines belonging to an invalid force (see isForceValid)
211	 * are marked `valid: false`; the DOM layer (Phase 5) decides whether to
212	 * comment such lines out with `# `.
213	 */
214	export function toCommandLines(state: PendingState): CommandLine[] {
215	  throw new Error("not yet implemented — green phase");
216	}
