1	import { describe, expect, test } from "bun:test";
2	import { parseImportText } from "./import-parser";
3	import {
4	  computeStateValidity,
5	  isForceValid,
6	  orderedEntries,
7	  toCommandLines,
8	  type AddedForce,
9	  type PendingState,
10	  type SnapshotAttractor,
11	  type SnapshotComponent,
12	  type SnapshotForce,
13	} from "./model";
14	
15	const baseAttractor: SnapshotAttractor = {
16	  id: "A-01",
17	  name: "resilience",
18	  description: "system tolerates partial failure",
19	  positiveState: "graceful degradation",
20	  negativeState: "cascading failure",
21	};
22	
23	const baseComponent: SnapshotComponent = {
24	  name: "cli",
25	  description: "command-line interface",
26	  status: "actual",
27	  architectureSet: "iter1",
28	};
29	
30	const baseStressor: SnapshotForce = {
31	  id: "S-01",
32	  kind: "stressor",
33	  description: "queue backs up under load",
34	  attractorId: "A-01",
35	  naiveChangeOrFeature: "add retry",
36	  outcomes: "requests drain",
37	  shortname: "queue-overload",
38	  components: ["cli"],
39	};
40	
41	function emptyState(overrides: Partial<PendingState> = {}): PendingState {
42	  return {
43	    baseAttractors: [],
44	    baseComponents: [],
45	    baseForces: [],
46	    basePersonas: [],
47	    baseTerms: [],
48	    addedAttractors: [],
49	    addedComponents: [],
50	    addedForces: [],
51	    addedPersonas: [],
52	    addedTerms: [],
53	    updatedAttractors: {},
54	    updatedComponents: {},
55	    updatedForces: {},
56	    updatedPersonas: {},
57	    updatedTerms: {},
58	    ...overrides,
59	  };
60	}
61	
62	describe("isForceValid", () => {
63	  test("valid when all required fields are set and at least one component is toggled", () => {
64	    expect(
65	      isForceValid({
66	        description: "queue backs up under load",
67	        attractorId: "A-01",
68	        naiveChangeOrFeature: "add retry",
69	        components: ["cli"],
70	      }),
71	    ).toBe(true);
72	  });
73	
74	  test("invalid when description is empty", () => {
75	    expect(
76	      isForceValid({
77	        description: "",
78	        attractorId: "A-01",
79	        naiveChangeOrFeature: "add retry",
80	        components: ["cli"],
81	      }),
82	    ).toBe(false);
83	  });
84	
85	  test("invalid when attractor-id is empty", () => {
86	    expect(
87	      isForceValid({
88	        description: "d",
89	        attractorId: "",
90	        naiveChangeOrFeature: "add retry",
91	        components: ["cli"],
92	      }),
93	    ).toBe(false);
94	  });
95	
96	  test("invalid when naive-change/feature is empty", () => {
97	    expect(
98	      isForceValid({
99	        description: "d",
100	        attractorId: "A-01",
101	        naiveChangeOrFeature: "",
102	        components: ["cli"],
103	      }),
104	    ).toBe(false);
105	  });
106	
107	  test("invalid when zero components are toggled, even with all other fields set", () => {
108	    expect(
109	      isForceValid({
110	        description: "d",
111	        attractorId: "A-01",
112	        naiveChangeOrFeature: "add retry",
113	        components: [],
114	      }),
115	    ).toBe(false);
116	  });
117	
118	  test("empty outcomes does NOT invalidate — outcomes is required:false in cli-schema.json", () => {
119	    // isForceValid's parameter type has no `outcomes` field at all: it is
120	    // never part of the check, by design.
121	    expect(
122	      isForceValid({
123	        description: "d",
124	        attractorId: "A-01",
125	        naiveChangeOrFeature: "add retry",
126	        components: ["cli"],
127	      }),
128	    ).toBe(true);
129	  });
130	});
131	
132	describe("computeStateValidity", () => {
133	  test("a base force whose pending update blanks a required field becomes invalid", () => {
134	    const state = emptyState({
135	      baseAttractors: [baseAttractor],
136	      baseForces: [baseStressor],
137	      updatedForces: { "S-01": { description: "" } },
138	    });
139	
140	    const validity = computeStateValidity(state);
141	
142	    expect(validity.invalidForceIds.has("S-01")).toBe(true);
143	    expect(validity.invalidReasonsByForce["S-01"]).toContain("description");
144	  });
145	
146	  test("an added force missing attractor-id is invalid, keyed by its tempId", () => {
147	    const addedForce: AddedForce = {
148	      tempId: "NEW-1",
149	      id: "",
150	      kind: "stressor",
151	      description: "d",
152	      attractorId: "",
153	      naiveChangeOrFeature: "n",
154	      outcomes: "",
155	      shortname: "",
156	      components: ["cli"],
157	    };
158	    const state = emptyState({ addedForces: [addedForce] });
159	
160	    const validity = computeStateValidity(state);
161	
162	    expect(validity.invalidForceIds.has("NEW-1")).toBe(true);
163	    expect(validity.invalidReasonsByForce["NEW-1"]).toContain("attractorId");
164	  });
165	
166	  test("a fully valid base force with no pending update is not flagged invalid", () => {
167	    const state = emptyState({
168	      baseAttractors: [baseAttractor],
169	      baseForces: [baseStressor],
170	    });
171	
172	    const validity = computeStateValidity(state);
173	
174	    expect(validity.invalidForceIds.has("S-01")).toBe(false);
175	  });
176	});
