178	describe("orderedEntries", () => {
179	  test("orders additions (component, attractor, persona, term, force) before all updates in the same bucket order", () => {
180	    const addedAttractor: SnapshotAttractor = {
181	      id: "",
182	      name: "new-attractor",
183	      description: "d",
184	      positiveState: "p",
185	      negativeState: "n",
186	    };
187	    const addedComponent: SnapshotComponent = {
188	      name: "gateway",
189	      description: "d",
190	      status: "proposed",
191	      architectureSet: "iter1",
192	    };
193	    const addedForce: AddedForce = {
194	      tempId: "NEW-1",
195	      id: "",
196	      kind: "stressor",
197	      description: "d",
198	      attractorId: "A-01",
199	      naiveChangeOrFeature: "n",
200	      outcomes: "",
201	      shortname: "",
202	      components: [], // no components: no synthetic update entry (see dedicated test below)
203	    };
204	
205	    const state = emptyState({
206	      baseAttractors: [baseAttractor],
207	      baseForces: [baseStressor],
208	      addedAttractors: [addedAttractor],
209	      addedComponents: [addedComponent],
210	      addedForces: [addedForce],
211	      updatedAttractors: { "A-01": { description: "revised" } },
212	      updatedForces: { "S-01": { description: "revised" } },
213	    });
214	
215	    expect(orderedEntries(state)).toEqual([
216	      { bucket: "component", action: "add", key: "gateway" },
217	      { bucket: "attractor", action: "add", key: "new-attractor" },
218	      { bucket: "force", action: "add", key: "NEW-1" },
219	      { bucket: "attractor", action: "update", key: "A-01" },
220	      { bucket: "force", action: "update", key: "S-01" },
221	    ]);
222	  });
223	
224	  test("an added force with toggled components emits an add entry AND a synthetic update entry, both keyed by its tempId", () => {
225	    const addedForce: AddedForce = {
226	      tempId: "NEW-1",
227	      id: "",
228	      kind: "stressor",
229	      description: "d",
230	      attractorId: "A-01",
231	      naiveChangeOrFeature: "n",
232	      outcomes: "",
233	      shortname: "",
234	      components: ["cli"],
235	    };
236	    const state = emptyState({ addedForces: [addedForce] });
237	
238	    expect(orderedEntries(state)).toEqual([
239	      { bucket: "force", action: "add", key: "NEW-1" },
240	      { bucket: "force", action: "update", key: "NEW-1" },
241	    ]);
242	  });
243	
244	  test("terms are ordered last in both the add phase and the update phase", () => {
245	    const addedTerm = { term: "hyperliminal coupling", definition: "d" };
246	    const addedComponent: SnapshotComponent = {
247	      name: "gateway",
248	      description: "d",
249	      status: "proposed",
250	      architectureSet: "iter1",
251	    };
252	    const state = emptyState({
253	      addedComponents: [addedComponent],
254	      addedTerms: [addedTerm],
255	      updatedTerms: { "hyperliminal coupling": { definition: "revised" } },
256	      updatedComponents: { cli: { description: "revised" } },
257	      baseComponents: [baseComponent],
258	    });
259	
260	    const entries = orderedEntries(state);
261	    const addIndices = entries
262	      .map((e, i) => ({ e, i }))
263	      .filter(({ e }) => e.action === "add")
264	      .map(({ i }) => i);
265	    const updateIndices = entries
266	      .map((e, i) => ({ e, i }))
267	      .filter(({ e }) => e.action === "update")
268	      .map(({ i }) => i);
269	
270	    expect(Math.max(...addIndices)).toBeLessThan(Math.min(...updateIndices));
271	    expect(entries[entries.findIndex((e) => e.bucket === "term" && e.action === "add")]).toEqual(
272	      { bucket: "term", action: "add", key: "hyperliminal coupling" },
273	    );
274	    expect(entries[entries.length - 1]).toEqual({
275	      bucket: "term",
276	      action: "update",
277	      key: "hyperliminal coupling",
278	    });
279	  });
280	});
