282	describe("toCommandLines", () => {
283	  test("renders a valid added stressor as a quoted `residual add stressor` line marked valid:true", () => {
284	    // No components toggled: the add line needs no shell-variable capture
285	    // (that's only required when a synthetic follow-up update needs the
286	    // real assigned id — see the dedicated with-components tests below).
287	    const addedForce: AddedForce = {
288	      tempId: "NEW-1",
289	      id: "",
290	      kind: "stressor",
291	      description: "queue backs up under load",
292	      attractorId: "A-01",
293	      naiveChangeOrFeature: "add retry",
294	      outcomes: "requests drain",
295	      shortname: "queue-overload",
296	      components: [],
297	    };
298	    const state = emptyState({ addedForces: [addedForce] });
299	
300	    const lines = toCommandLines(state);
301	    const addLine = lines.find((l) => l.line.startsWith("residual add stressor"));
302	
303	    expect(addLine).toBeDefined();
304	    expect(addLine!.valid).toBe(true);
