306	    expect(addLine!.line).toContain('--attractor-id "A-01"');
307	    expect(addLine!.line).toContain('--naive-change "add retry"');
308	  });
309	
310	  test("marks the line invalid when the underlying force fails validation", () => {
311	    const addedForce: AddedForce = {
312	      tempId: "NEW-1",
313	      id: "",
314	      kind: "stressor",
315	      description: "",
316	      attractorId: "A-01",
317	      naiveChangeOrFeature: "add retry",
318	      outcomes: "",
319	      shortname: "",
320	      components: [],
321	    };
322	    const state = emptyState({ addedForces: [addedForce] });
323	
324	    const lines = toCommandLines(state);
