331	  test("round-trips a generated `add stressor` line through parseImportText", () => {
332	    // No components toggled, so this stays a plain, directly-runnable
333	    // `residual add ...` line with no shell-variable capture wrapper —
334	    // see the with-components tests below for that case.
335	    const addedForce: AddedForce = {
336	      tempId: "NEW-1",
337	      id: "",
338	      kind: "stressor",
339	      description: 'text with "quotes" inside',
340	      attractorId: "A-01",
341	      naiveChangeOrFeature: "add retry",
342	      outcomes: "requests drain",
343	      shortname: "queue-overload",
344	      components: [],
345	    };
346	    const state = emptyState({ addedForces: [addedForce] });
347	
348	    const addLine = toCommandLines(state).find((l) =>
349	      l.line.startsWith("residual add stressor"),
350	    )!;
351	    const parsed = parseImportText(addLine.line);
352	
353	    expect(parsed.errors).toHaveLength(0);
354	    expect(parsed.items).toHaveLength(1);
355	    const item = parsed.items[0]!;
356	    expect(item.kind).toBe("add");
357	    expect(item.type).toBe("stressor");
358	    expect(item.fields.description).toBe('text with "quotes" inside');
359	    expect(item.fields["attractor-id"]).toBe("A-01");
360	    expect(item.fields["naive-change"]).toBe("add retry");
361	  });
362	
363	  test("an added force's real id is not known until `add stressor` actually runs (it has no --force-id flag — id is server-assigned and only printed on success as 'Added stressor S-NN'), so a synthetic component-toggle update MUST NOT reference the tempId as a literal --force-id value — that string will never exist in residues.csv/stressors.csv and the generated script would silently fail", () => {
364	    const addedForce: AddedForce = {
365	      tempId: "NEW-1",
366	      id: "",
367	      kind: "stressor",
368	      description: "d",
369	      attractorId: "A-01",
370	      naiveChangeOrFeature: "n",
371	      outcomes: "",
372	      shortname: "",
373	      components: ["cli"],
374	    };
375	    const state = emptyState({ addedForces: [addedForce] });
376	    const lines = toCommandLines(state);
377	
378	    const addLine = lines.find((l) => l.line.includes("residual add stressor"))!;
379	    const updateLine = lines.find((l) => l.line.includes("residual update stressor"))!;
380	
381	    // The add line captures the real assigned id into a shell variable
382	    // derived from the tempId (sanitized: non-alphanumeric -> "_", suffixed
383	    // "_ID") instead of emitting a bare `residual add ...` invocation.
384	    expect(addLine.line.startsWith("NEW_1_ID=$(residual add stressor")).toBe(true);
385	    expect(addLine.line).toContain("residual add stressor");
386	    expect(addLine.line).toContain('--description "d"');
387	    // Whatever the exact capture mechanism, it must extract the id token
388	    // `residual add stressor` prints on success ("Added stressor S-NN").
389	    expect(addLine.line).toMatch(/\)\s*$/);
390	
